pub fn glyph_name_at(index: u16) -> &'static str {
    if index as usize >= GLYPH_NAME_INDEX.len() {
        return "";
    }
    GLYPH_NAME_INDEX[index as usize].0
}

pub fn encoding_glyph_name(encoding: BuiltinEncoding, code: u8) -> &'static str {
    let table = match encoding {
        BuiltinEncoding::WinAnsi => &ENCODING_TABLES[0],
        BuiltinEncoding::Standard => &ENCODING_TABLES[1],
        BuiltinEncoding::MacRoman => &ENCODING_TABLES[2],
        BuiltinEncoding::MacExpert => &ENCODING_TABLES[3],
        BuiltinEncoding::Symbol => &ENCODING_TABLES[4],
        BuiltinEncoding::ZapfDingbats => &ENCODING_TABLES[5],
        BuiltinEncoding::PdfDoc => &ENCODING_TABLES[6],
        BuiltinEncoding::Custom => return "",
    };
    let idx = table[code as usize];
    if idx == 0xffff {
        return "";
    }
    glyph_name_at(idx)
}

pub fn lookup_agl(name: &[u8]) -> Option<&[u32]> {
    let name_str = core::str::from_utf8(name).ok()?;
    let mut lo = 0usize;
    let mut hi = AGL_NAME_OFFSETS.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let start = AGL_NAME_OFFSETS[mid] as usize;
        let end = if mid + 1 < AGL_NAME_OFFSETS.len() {
            AGL_NAME_OFFSETS[mid + 1] as usize
        } else {
            AGL_NAME_BLOB.len()
        };
        let entry = core::str::from_utf8(&AGL_NAME_BLOB[start..end]).ok()?;
        let entry = entry.trim_end_matches('\0');
        if entry == name_str {
            let cp_start = AGL_CODEPOINT_STARTS[mid] as usize;
            let mut cp_end = cp_start;
            while cp_end < AGL_CODEPOINTS.len() && AGL_CODEPOINTS[cp_end] != 0 {
                cp_end += 1;
            }
            return Some(&AGL_CODEPOINTS[cp_start..cp_end]);
        }
        if entry < name_str {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}
